-- The score thresholds (not dated, whole numbers): while both are set, a person whose score is at or
-- above the high one is in band HIGH, at or above the mid one MID, else LOW. Null means blank.
ALTER TABLE sheet ADD COLUMN score_mid INTEGER;
ALTER TABLE sheet ADD COLUMN score_high INTEGER;
    /**
     * A sheet as the screen shows it; the floor, the terms, the late percent and the cap are those in
     * force on its today: the floor has two decimals, the terms are in days, the late percent has two
     * decimals; the policy date is null when blank (the sheet's today); the cap has two decimals, null
     * when none; dated has every value recorded for its dated settings, by key; archived is whether a
     * steward has archived it; last batch is the number of its last bulk settle batch, null when none; the review SLA is in days, null when none;
     * the score mid and score high are whole numbers, null when blank;
     * role is the role the signed-in user acts in on it (clerk, steward, viewer or restricted) on its today.
     */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct,
            LocalDate policyDate, String cap, Map<String, List<SettingController.DatedView>> dated,
            boolean archived, Integer lastBatch, Integer reviewSla, String role, Integer scoreMid,
            Integer scoreHigh) {
        static SheetView of(Sheet sheet, Role role) {
            LocalDate today = sheet.getToday();
            return new SheetView(sheet.getId(), today, sheet.floorOn(today).toPlainString(),
                    sheet.termsOn(today), sheet.latePctOn(today).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    SettingController.datedViews(sheet.getDated()), sheet.isArchived(),
                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(), sheet.getReviewSla(),
                    role.label(), sheet.getScoreMid(), sheet.getScoreHigh());
        }
    }

    public record TodayRequest(@NotNull LocalDate today) {}

     * the parent is the id of the sheet it names as its parent, null when none; the fiscal start month
     * is the month (1 to 12) a fiscal year starts in; the alert threshold has two decimals, null when off;
     * the escalate after is a whole number of days, null when blank (off); so is the review SLA (none); the
     * default grade is one of the grades, null when blank (A); the score mid and score high are whole
     * numbers, null when blank.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, List<RoleView> roles, Map<String, Integer> gradeTerms, String cap,
            Map<String, List<DatedView>> dated, Map<String, String> permissions, Integer graceDays,
            LocalDate entryDate, String pot, String parent, int fiscalStartMonth, String alertThreshold,
            Integer escalateAfter, Integer reviewSla, String proofKinds, String defaultGrade, Integer scoreMid,
            Integer scoreHigh) {}

    /** A value recorded for a dated setting from a date on; null when none. */
    public record DatedView(LocalDate from, String value) {}

    /** Escalate after: a whole number of days; blank or null: off. */
    public record EscalateAfterRequest(@Pattern(regexp = "(\\d{1,4})?") String value) {

        Integer daysValue() {
            return value == null || value.isEmpty() ? null : Integer.valueOf(value);
        }
    }

    /** A score threshold (mid or high): a whole number; blank or null: blank. */
    public record ScoreThresholdRequest(@Pattern(regexp = "(-?\\d{1,6})?") String value) {

        Integer scoreValue() {
            return value == null || value.isEmpty() ? null : Integer.valueOf(value);
        }
    }

    /** Review SLA: a whole number of days; blank or null: none. */
    public record ReviewSlaRequest(@Pattern(regexp = "(\\d{1,4})?") String value) {

        Integer daysValue() {
            return value == null || value.isEmpty() ? null : Integer.valueOf(value);
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new SettingsView(text(service.clerkLimit(sheetId)), text(service.floor(sheetId)),
                service.terms(sheetId), text(service.latePct(sheetId)), service.policyDate(sheetId),
                service.periodNumberingFrom(sheetId),
                service.roles(sheetId).stream().map(RoleView::of).toList(), service.gradeTerms(sheetId),
                text(service.cap(sheetId)), datedViews(service.dated(sheetId)), service.permissions(sheetId),
                service.graceDays(sheetId), service.entryDate(sheetId), text(service.pot(sheetId)),
                service.parent(sheetId), service.fiscalStartMonth(sheetId), text(service.alertThreshold(sheetId)),
                service.escalateAfter(sheetId), service.reviewSla(sheetId),
                String.join(",", service.proofKinds(sheetId)), service.defaultGrade(sheetId),
                service.scoreMid(sheetId), service.scoreHigh(sheetId));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @RequestBody @Valid ReviewSlaRequest request) {
        service.setReviewSla(sheetId, user, request.daysValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/score-mid")
    public SettingsView setScoreMid(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ScoreThresholdRequest request) {
        service.setScoreMid(sheetId, user, request.scoreValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/score-high")
    public SettingsView setScoreHigh(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ScoreThresholdRequest request) {
        service.setScoreHigh(sheetId, user, request.scoreValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/escalate-after")
    public SettingsView setEscalateAfter(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
        sheets.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=grace-days value="
                + (days == null ? "" : days.toString()));
        return days;
    }

    /** Change the score mid threshold (null: blank); no stored figure changes with it. */
    @Transactional
    public Integer setScoreMid(String sheetId, String user, Integer score) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setScoreMid(score);
        sheets.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=score-mid value="
                + (score == null ? "" : score.toString()));
        return score;
    }

    /** Change the score high threshold (null: blank); no stored figure changes with it. */
    @Transactional
    public Integer setScoreHigh(String sheetId, String user, Integer score) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setScoreHigh(score);
        sheets.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=score-high value="
                + (score == null ? "" : score.toString()));
        return score;
    }

    /** Change the escalation gap in days (null: off). */
    @Transactional
    public Integer setEscalateAfter(String sheetId, String user, Integer days) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getEscalateAfter();
    }

    /** The score mid threshold as set; null when blank. */
    @Transactional(readOnly = true)
    public Integer scoreMid(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getScoreMid();
    }

    /** The score high threshold as set; null when blank. */
    @Transactional(readOnly = true)
    public Integer scoreHigh(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getScoreHigh();
    }

    /** The review SLA in days as set; null when blank, which means none. */
    @Column(name = "review_sla")
    private Integer reviewSla;

    /** A person whose score is at or above this is in band MID, while the high one is set too (not dated); null means blank. */
    @Column(name = "score_mid")
    private Integer scoreMid;

    /** A person whose score is at or above this is in band HIGH, while the mid one is set too (not dated); null means blank. */
    @Column(name = "score_high")
    private Integer scoreHigh;

    /** The month (1 to 12) a fiscal year starts in (not dated); 1 unless set. */
    public void setReviewSla(Integer reviewSla) { this.reviewSla = reviewSla; }

    public Integer getScoreMid() { return scoreMid; }

    public void setScoreMid(Integer scoreMid) { this.scoreMid = scoreMid; }

    public Integer getScoreHigh() { return scoreHigh; }

    public void setScoreHigh(Integer scoreHigh) { this.scoreHigh = scoreHigh; }

    public void setEscalateAfter(Integer escalateAfter) { this.escalateAfter = escalateAfter; }

