      this.error.set('Enter a grade\'s clerk limit of 0.00 or more, with at most two decimals, or leave it blank for the sheet\'s.');
      return;
    }
    if (floor.dirty && !/^\d{1,12}(\.\d{1,2})?$/.test(floorValue)) {
