    const gradeGraceChanged = GRADES.filter((g) => this.gradeGraceForm.controls[g].dirty);
    if (gradeGraceChanged.some((g) => !/^(\d{1,4})?$/.test(this.gradeGraceForm.controls[g].value.trim()))) {
